mapper.select:
SELECT id, userId, goodsName, `describe`, goodsPrice, goodsStock, imagePath, launch, preId, createTime, `delete`
FROM goods

    AND userId = #{entity.userId}
    AND launch = #{entity.launch}
    AND `delete` = 0

SELECT b.id, b.userId, b.imagePath, b.sequence, b.createTime, u.userName, u.avatarPath, u.`describe`, u.level, u.level AS vipLevel, u.level AS vipLevelName, u.`delete` FROM background b LEFT JOIN user u ON b.userId = u.id
AND b.userId = #{entity.userId}
ORDER BY b.sequence ASC
